Ippolito_2024_pacmilimab_qsp <- function() {
  description <- paste(
    "QSP. Quantitative systems pharmacology model of immuno-oncology (QSP-IO)",
    "describing the antitumour immune response to pacmilimab, a conditionally",
    "activated (Probody) anti-PD-L1 antibody, in triple-negative breast cancer.",
    "Four physiological compartments (central, peripheral, tumour, tumour-draining",
    "lymph node) plus APC endosomal and surface compartments, three",
    "immunological-synapse compartments (T cell-cancer cell, T cell-APC,",
    "macrophage-cancer cell) and four out-of-synapse compartments introduced by",
    "this paper (cancer cell, T cell, macrophage, APC). Covers Gompertzian",
    "tumour growth with explicit tumour vasculature, naive and activated",
    "CD4+/CD8+ T cell trafficking and proliferation, self- and neo-antigen",
    "release, uptake, endosomal processing and MHC-I presentation, TCR-mediated",
    "activation, PD-1/PD-L1/PD-L2 and CTLA-4/CD28/CD80/CD86 checkpoint binding,",
    "MDSC recruitment with arginase-I and nitric-oxide suppression, M1/M2",
    "tumour-associated macrophages with CD47/SIRP-alpha phagocytosis control, and",
    "IL-2 / IL-10 / IL-12 / IFN-gamma / TGF-beta / CCL2 dynamics. The Probody",
    "module carries six free states per compartment (masked, open and cleaved",
    "combinations of the two active sites) with reversible unmasking and",
    "irreversible protease cleavage, plus nine mono- and bivalently bound states",
    "at each of nine PD-L1 bearing sites. Dosing the fully masked state P_mm",
    "gives pacmilimab; dosing the fully cleaved state P_cc gives the unmasked",
    "anti-PD-L1 antibody (equivalent to atezolizumab monotherapy), which is how",
    "the paper simulates its reference arm. Deterministic mechanism model: the",
    "authors generated virtual patients by Latin hypercube sampling of the",
    "distributions in Supplementary Table S1 rather than by fitting IIV or",
    "residual error, so no etas and no error model are encoded.",
    sep = " "
  )
  reference <- paste(
    "Ippolito A, Wang H, Zhang Yu, Vakil V, Bazzazi H, Popel AS. Eliciting the",
    "antitumor immune response with a conditionally activated PD-L1 targeting",
    "antibody analyzed with a quantitative systems pharmacology model. CPT",
    "Pharmacometrics Syst Pharmacol. 2024;13(1):93-105. doi:10.1002/psp4.13060.",
    "Structure of the inherited QSP-IO platform from the SimBiology export in",
    "Wang H, Zhao C, Santa-Maria CA, Emens LA, Popel AS. Dynamics of",
    "tumor-associated macrophages in a quantitative systems pharmacology model of",
    "immunotherapy in triple-negative breast cancer. iScience.",
    "2022;25(8):104702. doi:10.1016/j.isci.2022.104702.",
    sep = " "
  )
  vignette <- "Ippolito_2024_pacmilimab_qsp"

  units <- list(
    time          = "day",
    dosing        = "nmol",
    concentration = "nmol/L"
  )

  covariateData <- list()

  population <- list(
    species       = "human (in silico virtual cohort)",
    n_subjects    = 10000L,
    disease_state = "triple-negative breast cancer",
    dose_range    = paste(
      "Pacmilimab 10 mg/kg every 2 weeks for 400 days is the reference regimen",
      "(the schedule selected in the phase I trial); the paper additionally",
      "explores 1, 3, 10 and 15 mg/kg at q1w, q2w, q3w and q4w, and single doses",
      "of 0.1, 0.3, 1, 3 and 10 mg/kg for the PK calibration.",
      sep = " "
    ),
    notes = paste(
      "Virtual cohort of 10,000 patients generated by Latin hypercube sampling of",
      "the 29 parameter distributions in Supplementary Table S1, then pruned to",
      "plausible patients. Each patient is grown from a small cancer-cell",
      "population to the pre-treatment tumour size before dosing starts. The",
      "clinical anchors are the pacmilimab phase I trial (16 patients with TNBC,",
      "objective response rate 7%) and the single-dose PK of Stroh 2021.",
      sep = " "
    )
  )
  ini({
    # ---- compartment capacities (Wang 2022 Table S6) ----
    vol_V_C <- fixed(5); label("Capacity of compartment V_C [liter]")  # Wang 2022 Table S6 (V_C = 5 liter)
    vol_V_P <- fixed(60); label("Capacity of compartment V_P [liter]")  # Wang 2022 Table S6 (V_P = 60 liter)
    vol_V_LN <- fixed(0.00111264739815); label("Capacity of compartment V_LN [millimeter^3]")  # Wang 2022 Table S6 (V_LN = 1112.64739814639 millimeter^3)
    vol_V_e <- fixed(4e-16); label("Capacity of compartment V_e [litre]")  # Wang 2022 Table S6 (V_e = 4e-16 litre)
    vol_A_e <- fixed(1.5e-09); label("Capacity of compartment A_e [micrometer^2]")  # Wang 2022 Table S6 (A_e = 15 micrometer^2)
    vol_A_s <- fixed(9e-08); label("Capacity of compartment A_s [micrometer^2]")  # Wang 2022 Table S6 (A_s = 900 micrometer^2)
    vol_syn_T_C1 <- fixed(3.78e-09); label("Capacity of compartment syn_T_C1 [micrometer^2]")  # Wang 2022 Table S6 (syn_T_C1 = 37.8 micrometer^2)
    vol_syn_T_APC <- fixed(3.78e-09); label("Capacity of compartment syn_T_APC [micrometer^2]")  # Wang 2022 Table S6 (syn_T_APC = 37.8 micrometer^2)
    vol_syn_M_C <- fixed(3.78e-09); label("Capacity of compartment syn_M_C [micrometer^2]")  # Wang 2022 Table S6 (syn_M_C = 37.8 micrometer^2)

