    k_cell_clear <- fixed(0.1); label("Rate of dead cell clearance from tumour compartment (estimated) [1/day]")  # Ippolito Table S2 (k_cell_clear = 0.1 1/day)
    cell <- fixed(1); label("unit parameter for calculation [cell]")  # Ippolito Table S2 (cell = 1 cell)
    day <- fixed(1); label("unit parameter for calculation [day]")  # Ippolito Table S2 (day = 1 day)
    vol_cell <- fixed(2.57244078451e-12); label("Average volume of cancer cell Volume of a cancer cell calculated based on cancer cell... [micrometer^3/cell]")  # Ippolito Table S2 (vol_cell = 2572.44078451444 micrometer^3/cell)
    vol_Tcell <- fixed(1.750157098e-13); label("Average volume of T cells Volume of a T cell calculated based on the average T cell d... [micrometer^3/cell]")  # Ippolito Table S2 (vol_Tcell = 175.015709799539 micrometer^3/cell)
    Ve_T <- fixed(0.37); label("Void fraction of the tumor (Finley 2012, PMID: 22547351) [dimensionless]")  # Ippolito Table S2 (Ve_T = 0.37 dimensionless)
    k_C1_growth <- fixed(0.0075); label("Cancer cell growth rate (Ryu 2014, PMID: 24895040; Desai 2006, PMID: 16489089) [1/day]")  # Ippolito Table S2 (k_C1_growth = 0.0075 1/day)
    k_K_g <- fixed(3.9); label("Tumour vasculature growth rate (Desai 2006, PMID: 16489089) [1/day]")  # Ippolito Table S2 (k_K_g = 3.9 1/day)
    k_K_d <- fixed(0.0023); label("Tumour vasculature inhibition rate (Desai 2006, PMID: 16489089; Hahnfeldt 1999, PMID:... [1/day]")  # Ippolito Table S2 (k_K_d = 0.0023 1/day)
    k_vas_Csec <- fixed(0.00011); label("Secretion rate of angiogenic factors by cancer cells (Volk 2008, PMID: 18516298) [picogram/cell/day]")  # Ippolito Table S2 (k_vas_Csec = 0.00011 picogram/cell/day)
    k_vas_deg <- fixed(16.6); label("Degradation rate of angiogenic factors (Finley 2011, PMID: 22104283) [1/day]")  # Ippolito Table S2 (k_vas_deg = 16.6 1/day)
    c_vas_50 <- fixed(839000); label("Half-maximal conc. of angiogenic factor on tumor capacity growth (Desai 2006, PMID: 1... [picogram/milliliter]")  # Ippolito Table S2 (c_vas_50 = 839 picogram/milliliter)
    k_C1_death <- fixed(1e-04); label("Cancer cell death rate from innate immune cells (Palsson 2013, PMID: 24074340) [1/day]")  # Ippolito Table S2 (k_C1_death = 1e-04 1/day)
    k_C1_therapy <- fixed(0); label("Rate of C1 killing by therapy [1/day]")  # Ippolito Table S2 (k_C1_therapy = 0 1/day)
