    q_T0_LN_out <- fixed(24); label("Rate of activated T cell transport out of the LN (De Boer and Perelson 1995, PMID: 74... [1/day]")  # Ippolito Table S2 (q_T0_LN_out = 24 1/day)
    q_nT0_LN_out <- fixed(2.88); label("Rate of naive T cell transport out of the LN (Mandl 2012, PMID: 23071319) [1/day]")  # Ippolito Table S2 (q_nT0_LN_out = 2.88 1/day)
    k_T0_act <- fixed(5); label("T0 activation rate (De Boer and Perelson 1995, PMID: 7475092; Robertson-Tessi 2012, P... [1/day]")  # Ippolito Table S2 (k_T0_act = 5 1/day)
